package com.gzy.qinglian;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import android.widget.*;import com.google.android.material.materialswitch.MaterialSwitch;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class LabsTest {
 @After public void clear(){TunnelService.state="disconnected";RuntimeEnvironment.getApplication().getSharedPreferences("labs",0).edit().clear().commit();}
 @Test public void defaultOffAndOnlyAcceleratedProfileRequestsExperiment()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();assertFalse(LabSettings.enabled(c,"hy2"));assertFalse(LabSettings.profileOptions(c).getBoolean("labHy2"));LabSettings.set(c,"hy2",true);c.getSharedPreferences("transport",0).edit().putBoolean("accelerated",false).commit();assertFalse(LabSettings.profileOptions(c).getBoolean("labHy2"));c.getSharedPreferences("transport",0).edit().putBoolean("accelerated",true).commit();assertTrue(LabSettings.profileOptions(c).getBoolean("labHy2"));c.getSharedPreferences("transport",0).edit().clear().commit();}
 @Test public void laboratoryOpensAndSpeedOptionsPersist(){try(var controller=Robolectric.buildActivity(LabsActivity.class).setup()){LabsActivity a=controller.get();java.util.ArrayList<MaterialSwitch> switches=new java.util.ArrayList<>();walk(a.findViewById(android.R.id.content),switches);assertEquals(3,switches.size());switches.get(1).setChecked(true);assertTrue(LabSettings.enabled(a,"parallel"));TunnelService.state="connected";switches.get(0).setChecked(true);assertFalse(switches.get(0).isChecked());assertFalse(LabSettings.enabled(a,"hy2"));}}
 private void walk(android.view.View v,java.util.List<MaterialSwitch> out){if(v instanceof MaterialSwitch)out.add((MaterialSwitch)v);if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)walk(g.getChildAt(i),out);}}
}
